@dataclass
class HoltWintersConfig:
    """Mirror of the Rust HoltWintersConfig struct."""

    alpha: float
    beta: float
    gamma: float
    seasonality: int
    seasonal_mode: str  # "additive" | "multiplicative"

    def __post_init__(self) -> None:
        if not (0.0 < self.alpha < 1.0):
            raise ValueError("alpha must be in (0, 1)")
        if not (0.0 < self.beta < 1.0):
            raise ValueError("beta must be in (0, 1)")
        if not (0.0 < self.gamma < 1.0):
            raise ValueError("gamma must be in (0, 1)")
        if self.seasonality < 1:
            raise ValueError("seasonality must be >= 1")
        if self.seasonal_mode not in ("additive", "multiplicative"):
            raise ValueError("seasonal_mode must be 'additive' or 'multiplicative'")


class HoltWinters:
    """
    Reference implementation of Holt-Winters triple exponential smoothing.
    Mirrors the documented Rust API: fit(series) -> Self, forecast(horizon) -> Vec<f64>.
    """

    def __init__(self, config: HoltWintersConfig) -> None:
        self.config = config
        self._level: Optional[float] = None
        self._trend: Optional[float] = None
        self._seasonal: List[float] = []
        self._fitted: List[float] = []

    def fit(self, series: List[float]) -> "HoltWinters":
        """Fit the model to the provided series (in-place, returns self)."""
        if len(series) < 2 * self.config.seasonality:
            raise ValueError(
                f"series length ({len(series)}) must be at least "
                f"2 * seasonality ({2 * self.config.seasonality})"
            )

        n = len(series)
        s = self.config.seasonality
        alpha, beta, gamma = self.config.alpha, self.config.beta, self.config.gamma
        mode = self.config.seasonal_mode

        # Initial level: average of first season
        self._level = sum(series[:s]) / s
        # Initial trend: average of seasonal differences
        self._trend = (sum(series[s : 2 * s]) - sum(series[:s])) / (s * s)
        # Initial seasonal indices: normalized deviations from level
        self._seasonal = [0.0] * s
        for i in range(s):
            if mode == "additive":
                self._seasonal[i] = series[i] - self._level
            else:
                base = self._level + self._trend * (i + 1)
                self._seasonal[i] = series[i] / base if base != 0.0 else 1.0

        # Iterative smoothing
        level, trend = self._level, self._trend
        seasonal = self._seasonal[:]
        self._fitted = []

        for t in range(n):
            idx = t % s
            if mode == "additive":
                fitted = level + trend + seasonal[idx]
                new_level = alpha * (series[t] - seasonal[idx]) + (1 - alpha) * (level + trend)
                new_trend = beta * (new_level - level) + (1 - beta) * trend
                new_seasonal = gamma * (series[t] - new_level) + (1 - gamma) * seasonal[idx]
            else:
                fitted = (level + trend) * seasonal[idx]
                new_level = alpha * (series[t] / seasonal[idx] if seasonal[idx] != 0.0 else series[t]) + (1 - alpha) * (level + trend)
                new_trend = beta * (new_level - level) + (1 - beta) * trend
                new_seasonal = gamma * (series[t] / new_level if new_level != 0.0 else 1.0) + (1 - gamma) * seasonal[idx]

            self._fitted.append(fitted)
            level, trend = new_level, new_trend
            seasonal[idx] = new_seasonal

        self._level, self._trend = level, trend
        self._seasonal = seasonal
        return self

    def forecast(self, horizon: int) -> List[float]:
        """Generate forecasts for the next `horizon` steps."""
        if self._level is None or self._trend is None or not self._seasonal:
            raise RuntimeError("model must be fit before forecasting")
        if horizon < 1:
            raise ValueError("horizon must be >= 1")

        s = self.config.seasonality
        mode = self.config.seasonal_mode
        result = []
        for h in range(1, horizon + 1):
            idx = (len(self._fitted) + h - 1) % s
            if mode == "additive":
                result.append(self._level + h * self._trend + self._seasonal[idx])
            else:
                result.append((self._level + h * self._trend) * self._seasonal[idx])
        return result


# ---------------------------------------------------------------------------
# Fixtures and synthetic data generators
# ---------------------------------------------------------------------------


def generate_additive_series(
    n: int, seasonality: int, level: float = 100.0, trend: float = 0.5,
    amplitude: float = 10.0, noise: float = 0.0, seed: int = 42,
) -> List[float]:
    """Generate an additive seasonal series: y = level + trend*t + amplitude*sin(2πt/s)."""
    rng = random.Random(seed)
    series = []
    for t in range(n):
        seasonal = amplitude * math.sin(2.0 * math.pi * t / seasonality)
        value = level + trend * t + seasonal + rng.gauss(0.0, noise)
        series.append(value)
    return series


def generate_multiplicative_series(
    n: int, seasonality: int, level: float = 100.0, trend: float = 0.3,
    amplitude: float = 0.2, noise: float = 0.0, seed: int = 7,
) -> List[float]:
    """Generate a multiplicative seasonal series: y = (level + trend*t) * (1 + amplitude*sin(2πt/s))."""
    rng = random.Random(seed)
    series = []
    for t in range(n):
        seasonal = 1.0 + amplitude * math.sin(2.0 * math.pi * t / seasonality)
        value = (level + trend * t) * seasonal + rng.gauss(0.0, noise)
        series.append(value)
    return series


