class TestResourceBudgetAndDeterminism:
    """Verify O(1) memory behavior, determinism, and no-panic guarantees."""

    def test_deterministic_fit(self, additive_config: HoltWintersConfig, clean_additive_series: List[float]) -> None:
        model1 = HoltWinters(additive_config)
        model2 = HoltWinters(additive_config)
        model1.fit(clean_additive_series)
        model2.fit(clean_additive_series)
        assert model1._fitted == model2._fitted
        assert model1._level == model2._level
        assert model1._trend == model2._trend
        assert model1._seasonal == model2._seasonal

    def test_deterministic_forecast(self, additive_config: HoltWintersConfig, clean_additive_series: List[float]) -> None:
        model1 = HoltWinters(additive_config)
        model2 = HoltWinters(additive_config)
        model1.fit(clean_additive_series)
        model2.fit(clean_additive_series)
        assert model1.forecast(20) == model2.forecast(20)

    def test_state_size_constant(self, additive_config: HoltWintersConfig) -> None:
        """Verify O(1) memory: state size independent of series length."""
        model = HoltWinters(additive_config)
        model.fit([1.0] * 100)
        state_100 = (model._level, model._trend, len(model._seasonal))
        model.fit([1.0] * 10000)
        state_10000 = (model._level, model._trend, len(model._seasonal))
        # Seasonal vector length is fixed by config, not series length
        assert state_100[2] == state_10000[2] == additive_config.seasonality

    def test_no_panic_on_extreme_values(self, additive_config: HoltWintersConfig) -> None:
        """Extreme values should not cause panics (Rust) or exceptions (Python)."""
        extreme_series = [1e308, -1e308, 1e-308, -1e-308, 0.0] * 20
        model = HoltWinters(additive_config)
        try:
            model.fit(extreme_series)
            model.forecast(5)
        except (OverflowError, FloatingPointError):
            pytest.skip("Extreme values may cause float overflow in reference impl")

    def test_no_panic_on_nan_inf(self, additive_config: HoltWintersConfig) -> None:
        """NaN/Inf inputs should be handled gracefully (no panic)."""
        series = [float("nan"), 1.0, 2.0, 3.0] * 20
        model = HoltWinters(additive_config)
        try:
            model.fit(series)
            model.forecast(5)
        except (ValueError, FloatingPointError):
            pytest.skip("NaN handling is implementation-defined")


