class TestPropertyBased:
    """Property-based tests using hypothesis for broader coverage."""

    @pytest.mark.parametrize("mode", ["additive", "multiplicative"])
    def test_forecast_length_matches_horizon(self, mode: str) -> None:
        from hypothesis import given, settings, strategies as st

        @given(
            alpha=st.floats(min_value=0.01, max_value=0.99),
            beta=st.floats(min_value=0.01, max_value=0.99),
            gamma=st.floats(min_value=0.01, max_value=0.99),
            seasonality=st.integers(min_value=1, max_value=48),
            n=st.integers(min_value=2, max_value=500),
            horizon=st.integers(min_value=1, max_value=100),
        )
        @settings(max_examples=50, deadline=None)
        def _check(alpha: float, beta: float, gamma: float, seasonality: int, n: int, horizon: int) -> None:
            config = HoltWintersConfig(alpha=alpha, beta=beta, gamma=gamma, seasonality=seasonality, seasonal_mode=mode)
            series = [math.sin(i) * 10 + i * 0.1 for i in range(n * seasonality)]
            model = HoltWinters(config)
            model.fit(series)
            forecasts = model.forecast(horizon)
            assert len(forecasts) == horizon
            assert all(math.isfinite(f) for f in forecasts)

        _check()

    @pytest.mark.parametrize("mode", ["additive", "multiplicative"])
    def test_fit_never_raises_on_valid_input(self, mode: str) -> None:
        from hypothesis import given, settings, strategies as st

        @given(
            alpha=st.floats(min_value=0.01, max_value=0.99),
            beta=st.floats(min_value=0.01, max_value=0.99),
            gamma=st.floats(min_value=0.01, max_value=0.99),
            seasonality=st.integers(min_value=1, max_value=24),
            n=st.integers(min_value=2, max_value=100),
        )
        @settings(max_examples=50, deadline=None)
        def _check(alpha: float, beta: float, gamma: float, seasonality: int, n: int) -> None:
            config = HoltWintersConfig(alpha=alpha, beta=beta, gamma=gamma, seasonality=seasonality, seasonal_mode=mode)
            series = [float(i % 7) for i in range(n * seasonality)]
            model = HoltWinters(config)
            model.fit(series)  # Should not raise

        _check()


