class TestNumericalStability:
    """Verify numerical stability across parameter ranges."""

    @pytest.mark.parametrize("alpha,beta,gamma", [
        (0.01, 0.01, 0.01),  # Very slow adaptation
        (0.99, 0.99, 0.99),  # Very fast adaptation
        (0.5, 0.5, 0.5),     # Balanced
        (0.1, 0.9, 0.1),     # High trend sensitivity
        (0.9, 0.1, 0.9),     # High level/seasonal sensitivity
    ])
    def test_parameter_sweep_stability(self, alpha: float, beta: float, gamma: float) -> None:
        config = HoltWintersConfig(alpha=alpha, beta=beta, gamma=gamma, seasonality=12, seasonal_mode="additive")
        series = generate_additive_series(n=240, seasonality=12, noise=1.0, seed=99)
        model = HoltWinters(config)
        model.fit(series)
        forecasts = model.forecast(24)
        assert all(math.isfinite(f) for f in forecasts)
        # Forecasts should not explode
        assert all(abs(f) < 1e6 for f in forecasts)

    def test_single_seasonality(self) -> None:
        """Seasonality=1 should behave like simple exponential smoothing with trend."""
        config = HoltWintersConfig(alpha=0.3, beta=0.1, gamma=0.2, seasonality=1, seasonal_mode="additive")
        series = [float(i) for i in range(100)]
        model = HoltWinters(config)
        model.fit(series)
        forecasts = model.forecast(10)
        # Should continue the linear trend
        assert forecasts[0] > 95.0
        assert forecasts[-1] > forecasts[0]

    def test_large_seasonality(self) -> None:
        """Large seasonality should still work correctly."""
        config = HoltWintersConfig(alpha=0.3, beta=0.1, gamma=0.2, seasonality=168, seasonal_mode="additive")
        series = generate_additive_series(n=336, seasonality=168, noise=0.0)
        model = HoltWinters(config)
        model.fit(series)
        forecasts = model.forecast(168)
        assert len(forecasts) == 168
        assert all(math.isfinite(f) for f in forecasts)


