class TestIntegration:
    """End-to-end pipeline tests simulating real usage."""

    def test_full_pipeline_additive(self) -> None:
        """Fit on historical data, forecast future, verify RMSE."""
        series = generate_additive_series(n=500, seasonality=24, trend=0.8, amplitude=15.0, noise=0.5, seed=2024)
        train, test = series[:400], series[400:]

        config = HoltWintersConfig(alpha=0.4, beta=0.15, gamma=0.25, seasonality=24, seasonal_mode="additive")
        model = HoltWinters(config)
        model.fit(train)

        forecasts = model.forecast(len(test))
        rmse = math.sqrt(sum((f - a) ** 2 for f, a in zip(forecasts, test)) / len(test))
        # RMSE should be small relative to signal amplitude (15.0)
        assert rmse < 3.0, f"RMSE too high: {rmse}"

    def test_full_pipeline_multiplicative(self) -> None:
        """Fit on multiplicative series, forecast, verify relative error."""
        series = generate_multiplicative_series(n=500, seasonality=24, trend=0.5, amplitude=0.3, noise=0.01, seed=3030)
        train, test = series[:400], series[400:]

        config = HoltWintersConfig(alpha=0.3, beta=0.1, gamma=0.2, seasonality=24, seasonal_mode="multiplicative")
        model = HoltWinters(config)
        model.fit(train)

        forecasts = model.forecast(len(test))
        # Relative error should be small
        rel_errors = [abs(f - a) / abs(a) for f, a in zip(forecasts, test) if a != 0]
        mean_rel_error = sum(rel_errors) / len(rel_errors)
        assert mean_rel_error < 0.05, f"Mean relative error too high: {mean_rel_error}"

    def test_forecast_confidence_monotonic(self) -> None:
        """Forecast uncertainty should increase with horizon (if implemented)."""
        series = generate_additive_series(n=240, seasonality=24, noise=1.0)
        config = HoltWintersConfig(alpha=0.3, beta=0.1, gamma=0.2, seasonality=24, seasonal_mode="additive")
        model = HoltWinters(config)
        model.fit(series)
        # Point forecasts should be deterministic; this test verifies no regression
        f1 = model.forecast(10)
        f2 = model.forecast(10)
        assert f1 == f2


